def downgrade():
    raise RuntimeError(
        "R1 contains immutable business decisions; use compatible rollback build "
        "or restore verified backup"
    )


def _backfill():
    """Frozen migration rules from architecture §12.1; never infer employers."""
    import hashlib
    import json
    import uuid
    from datetime import UTC, datetime

    bind = op.get_bind()
    meta = sa.MetaData()

    def table(name):
        return sa.Table(name, meta, autoload_with=bind)

    def insert(table_name, **row):
        bind.execute(table(table_name).insert().values(**row))

    def ledger(kind, old_id, new_id, basis, confidence="confirmed_owner"):
        insert(
            "migration_ledger",
            id=uuid.uuid4(),
            legacy_kind=kind,
            legacy_id=old_id,
            new_id=new_id,
            basis=basis,
            confidence=confidence,
        )

    users = {
        u.username: u
        for u in bind.execute(sa.select(table("users"))).mappings()
        if u.username
    }
    owners = {}
    projects = table("projects")
    for p in bind.execute(sa.select(projects)).mappings():
        owner = users.get(p.owner_username)
        demo = p.code == "MANAGEMENT-DEMO" and p.owner_username is None
        if owner and owner.id in owners:
            org_id, membership_id = owners[owner.id]
        else:
            org_id, membership_id = uuid.uuid4(), uuid.uuid4() if owner else None
            insert(
                "organizations",
                id=org_id,
                name=f"Рабочая область {owner.username}"
                if owner
                else f"Миграционный карантин {p.code}",
                status="active",
                needs_confirmation=True,
            )
            if owner:
                insert(
                    "organization_memberships",
                    id=membership_id,
                    organization_id=org_id,
                    user_id=owner.id,
                    status="active",
                    can_manage_members=owner.role != "viewer",
                    can_create_projects=owner.role != "viewer",
                )
                owners[owner.id] = org_id, membership_id
                ledger(
                    "user",
                    owner.id,
                    membership_id,
                    "Exact existing owner_username; no global-role inference",
                )
        party_id = uuid.uuid4()
        insert(
            "project_organizations",
            id=party_id,
            project_id=p.id,
            organization_id=org_id,
            side="customer",
            status="active",
        )
        insert(
            "participation_periods",
            id=uuid.uuid4(),
            participation_id=party_id,
            started_at=datetime.now(UTC),
            ended_at=None,
        )
        bind.execute(
            projects.update()
            .where(projects.c.id == p.id)
            .values(
                customer_organization_id=org_id,
                kind="shared_demo" if demo else "production",
                lifecycle="archived" if p.status == "archived" else "active",
            )
        )
        if owner and not demo:
            assignment_id = uuid.uuid4()
            insert(
                "project_assignments",
                id=assignment_id,
                participation_id=party_id,
                membership_id=membership_id,
                role="project_viewer" if owner.role == "viewer" else "customer_manager",
                scope_kind="project",
                status="active",
                row_version=1,
            )
        ledger(
            "project",
            p.id,
            org_id,
            "Explicit shared fixture, read only"
            if demo
            else "Exact owner mapping"
            if owner
            else "Missing/ambiguous owner; no grants",
            "quarantined" if not owner and not demo else "confirmed_owner",
        )
        documents = table("ppr_documents")
        for d in bind.execute(
            sa.select(documents).where(documents.c.project_id == p.id)
        ).mappings():
            series_id = uuid.uuid4()
            insert(
                "document_series",
                id=series_id,
                project_id=p.id,
                owner_participation_id=party_id,
                title=d.filename,
            )
            uploader = users.get(d.uploaded_by)
            bind.execute(
                documents.update()
                .where(documents.c.id == d.id)
                .values(
                    series_id=series_id,
                    version_no=1,
                    owner_participation_id=party_id,
                    uploaded_by_user_id=uploader.id if uploader else None,
                )
            )
            ledger(
                "document",
                d.id,
                series_id,
                "Original ID/hash/storage preserved; approval not inferred",
                "legacy_unverified",
            )
        # Active flags survive as history; only a new approved release grants control.
        requirements = table("ppr_requirements")
        for r in bind.execute(
            sa.select(requirements).where(
                requirements.c.project_id == p.id, requirements.c.active.is_(True)
            )
        ).mappings():
            ledger(
                "requirement",
                r.id,
                None,
                "legacy_active; requires engineer review and customer release",
                "legacy_unverified",
            )
        incidents = table("incidents")
        events = table("incident_events")
        for inc in bind.execute(
            sa.select(incidents).where(incidents.c.project_id == p.id)
        ).mappings():
            auto = bind.scalar(
                sa.select(events.c.id)
                .where(
                    events.c.incident_id == inc.id, events.c.event_type == "auto_resolved"
                )
                .limit(1)
            )
            origin = (
                ("legacy_auto" if auto else "legacy_unverified")
                if inc.status == "resolved"
                else None
            )
            bind.execute(
                incidents.update()
                .where(incidents.c.id == inc.id)
                .values(
                    workflow_version=1,
                    resolution_origin=origin,
                    detected_at=None,
                    case_kind="control_integrity"
                    if inc.category == "camera"
                    else "construction",
                )
            )

            def iso(value):
                return (
                    value.replace(tzinfo=UTC) if value.tzinfo is None else value
                ).isoformat()

            snapshot = dict(
                schema_version=1,
                project_id=str(p.id),
                observed_from=iso(inc.first_seen_at),
                observed_until=iso(inc.last_seen_at),
                source_evidence_ids=[],
                detector_sha256=None,
                release_id=None,
                manifest_sha256=None,
                provenance="legacy",
                citations=[],
                coverage=dict(
                    status="unknown",
                    configuration_id=None,
                    camera_ids=[],
                    reasons=["unknown_geometry"],
                ),
                limitations=[
                    "Историческое основание; утверждение заказчиком не зафиксировано"
                ],
            )
            sha = hashlib.sha256(
                json.dumps(
                    snapshot, sort_keys=True, separators=(",", ":"), ensure_ascii=False
                ).encode()
            ).hexdigest()
            insert(
                "incident_basis",
                id=uuid.uuid4(),
                incident_id=inc.id,
                schema_version=1,
                snapshot=snapshot,
                sha256=sha,
                created_at=datetime.now(UTC),
            )
            ledger(
                "incident",
                inc.id,
                inc.id,
                "IDs, dates, explanation, dedup and historical status preserved",
                "legacy_unverified",
            )


def _constraints():
    # Legacy duplicates are retained and named in a ledger; no row is deleted.
    op.execute("""
        INSERT INTO migration_ledger
        (id,legacy_kind,legacy_id,new_id,basis,confidence) SELECT
        id,'legacy_open_duplicate',id,NULL,
        'Existing duplicate retained; row excluded from v2 unique',
        'legacy_unverified'
        FROM (SELECT id,row_number() OVER (PARTITION BY project_id,dedup_key
        ORDER BY first_seen_at,id) AS n FROM incidents WHERE status IN
        ('pending','confirmed','in_progress','remediation_submitted')) d WHERE
        n>1
    """)
    op.execute(
        """
        ALTER TABLE incidents ADD COLUMN legacy_duplicate BOOLEAN NOT NULL
        DEFAULT false
    """
    )
    op.execute(
        """
        UPDATE incidents SET legacy_duplicate=true WHERE id IN (SELECT legacy_id
        FROM migration_ledger WHERE legacy_kind='legacy_open_duplicate')
    """
    )
    op.execute("""
        CREATE UNIQUE INDEX uq_incidents_open_episode ON
        incidents(project_id,dedup_key) WHERE status IN
        ('pending','confirmed','in_progress','remediation_submitted') AND NOT
        legacy_duplicate
    """)
    op.execute(
        """
        CREATE UNIQUE INDEX uq_project_customer ON
        project_organizations(project_id) WHERE side='customer'
    """
    )
    op.execute(
        """
        CREATE UNIQUE INDEX uq_open_dispute ON disputes(incident_id) WHERE
        status='open'
    """
    )
    op.execute(
        """
        CREATE UNIQUE INDEX uq_camera_open_move ON
        camera_move_requests(camera_id) WHERE status IN
        ('requested','approved','in_progress','awaiting_reference')
    """
    )
    op.execute("""
        CREATE FUNCTION customer_control_relations() RETURNS trigger LANGUAGE
        plpgsql AS $$ DECLARE p uuid; org uuid; side text; parent_project uuid;
        BEGIN IF TG_TABLE_NAME='project_assignments' THEN SELECT
        organization_id,project_id,project_organizations.side INTO org,p,side
        FROM project_organizations WHERE id=NEW.participation_id; IF org IS
        DISTINCT FROM (SELECT organization_id FROM organization_memberships
        WHERE id=NEW.membership_id) OR (NEW.role='customer_manager' AND
        side<>'customer') OR (NEW.role='contractor_foreman' AND
        side<>'contractor') OR (side='contractor' AND NEW.scope_kind<>'areas')
        OR (NEW.role='customer_manager' AND NEW.scope_kind<>'project') THEN
        RAISE EXCEPTION 'Invalid assignment organization/side/scope' USING
        ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='project_organizations'
        THEN IF NEW.side='customer' AND NEW.organization_id IS DISTINCT FROM
        (SELECT customer_organization_id FROM projects WHERE id=NEW.project_id)
        THEN RAISE EXCEPTION 'Customer participation differs from owner' USING
        ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='responsibility_areas' THEN
        IF (NEW.zone_id IS NOT NULL AND NEW.project_id IS DISTINCT FROM (SELECT
        project_id FROM zones WHERE id=NEW.zone_id)) OR (NEW.schedule_task_id IS
        NOT NULL AND NEW.project_id IS DISTINCT FROM (SELECT project_id FROM
        schedule_tasks WHERE id=NEW.schedule_task_id)) OR (NEW.zone_id IS NOT
        NULL AND NEW.schedule_task_id IS NOT NULL AND EXISTS(SELECT 1 FROM
        schedule_tasks WHERE id=NEW.schedule_task_id AND zone_id IS NOT NULL AND
        zone_id<>NEW.zone_id)) THEN RAISE EXCEPTION
        'Area belongs to another project/zone' USING ERRCODE='23514'; END IF;
        ELSIF TG_TABLE_NAME='assignment_areas' THEN SELECT po.project_id INTO p
        FROM project_assignments a JOIN project_organizations po ON
        po.id=a.participation_id WHERE a.id=NEW.assignment_id; IF p IS DISTINCT
        FROM (SELECT project_id FROM responsibility_areas WHERE id=NEW.area_id)
        THEN RAISE EXCEPTION 'Assignment area belongs to another project' USING
        ERRCODE='23514'; END IF; ELSIF TG_TABLE_NAME='control_release_items'
        THEN IF (SELECT project_id FROM control_releases WHERE
        id=NEW.release_id) IS DISTINCT FROM (SELECT project_id FROM
        requirement_revisions WHERE id=NEW.revision_id) THEN RAISE EXCEPTION
        'Cross project release item' USING ERRCODE='23514'; END IF; ELSIF
        TG_TABLE_NAME='incident_evidence_links' THEN IF (SELECT project_id FROM
        incidents WHERE id=NEW.incident_id) IS DISTINCT FROM (SELECT project_id
        FROM evidence_assets WHERE id=NEW.asset_id) THEN RAISE EXCEPTION
        'Cross project evidence link' USING ERRCODE='23514'; END IF; END IF;
        RETURN NEW; END $$
    """)
    for name in (
        "project_assignments",
        "project_organizations",
        "responsibility_areas",
        "assignment_areas",
        "control_release_items",
        "incident_evidence_links",
    ):
        op.execute(
            f"CREATE TRIGGER ck_{name}_relations BEFORE INSERT OR UPDATE ON {name} "
            "FOR EACH ROW EXECUTE FUNCTION customer_control_relations()"
        )
    op.execute("""
        CREATE FUNCTION customer_control_immutable() RETURNS trigger LANGUAGE
        plpgsql AS $$ BEGIN IF TG_TABLE_NAME='requirement_revisions' AND
        TG_OP='UPDATE' AND NOT OLD.submitted THEN RETURN NEW; END IF; RAISE
        EXCEPTION 'Immutable customer-control record' USING ERRCODE='23514'; END
        $$
    """)
    for name in (
        "incident_basis",
        "evidence_assets",
        "remediation_submissions",
        "remediation_reviews",
        "dispute_decisions",
        "audit_events",
        "requirement_revisions",
    ):
        op.execute(
            f"CREATE TRIGGER immutable_{name} BEFORE UPDATE OR DELETE ON {name} "
            "FOR EACH ROW EXECUTE FUNCTION customer_control_immutable()"
        )
    # Protect originals/history even if a destructive legacy path is reintroduced.
    op.execute("""
        CREATE FUNCTION customer_control_keep_evidence() RETURNS trigger
        LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION
        'Business evidence cannot be deleted; archive the project' USING
        ERRCODE='23514'; END $$
    """)
    for name in (
        "projects",
        "cameras",
        "frames",
        "incidents",
        "incident_events",
        "incident_evidence",
        "ppr_documents",
        "ppr_pages",
        "ppr_analyses",
        "video_assets",
    ):
        op.execute(
            f"CREATE TRIGGER preserve_{name} BEFORE DELETE ON {name} "
            "FOR EACH ROW EXECUTE FUNCTION customer_control_keep_evidence()"
        )
